CREATE TABLE public.finance_accounts(id uuid PRIMARY KEY,household_id uuid NOT NULL REFERENCES public.finance_households(id),label text NOT NULL,currency text NOT NULL CHECK(currency='EUR'),UNIQUE(household_id,id));
CREATE TABLE public.finance_sources(id uuid PRIMARY KEY,household_id uuid NOT NULL REFERENCES public.finance_households(id),account_id uuid NOT NULL,drive_file_id text NOT NULL,file_name text NOT NULL,source_url text NOT NULL CHECK(source_url LIKE 'https://%'),content_sha256 text NOT NULL,first_on date NOT NULL,last_on date NOT NULL,row_count integer NOT NULL,balance_checks integer NOT NULL,warning text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(household_id,id),UNIQUE(household_id,drive_file_id,content_sha256),FOREIGN KEY(household_id,account_id) REFERENCES public.finance_accounts(household_id,id));
CREATE TABLE public.finance_transactions(id uuid PRIMARY KEY,household_id uuid NOT NULL REFERENCES public.finance_households(id),account_id uuid NOT NULL,booked_on date NOT NULL,operated_on date NOT NULL,valued_on date NOT NULL,description text NOT NULL,amount numeric(16,2) NOT NULL,statement_balance numeric(16,2) NOT NULL,fingerprint text NOT NULL,category text,suggested_category text,category_method text NOT NULL,flow_kind text NOT NULL CHECK(flow_kind IN ('expense','income','refund','investment','transfer','withdrawal','review','opening_balance')),review_status text NOT NULL CHECK(review_status IN ('suggested','needs_review','reviewed')),version integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid REFERENCES auth.users(id),UNIQUE(household_id,id),UNIQUE(household_id,fingerprint),FOREIGN KEY(household_id,account_id) REFERENCES public.finance_accounts(household_id,id));
CREATE TABLE public.finance_transaction_sources(household_id uuid NOT NULL,transaction_id uuid NOT NULL,source_id uuid NOT NULL,source_row integer NOT NULL CHECK(source_row>0),PRIMARY KEY(source_id,source_row),FOREIGN KEY(household_id,transaction_id) REFERENCES public.finance_transactions(household_id,id),FOREIGN KEY(household_id,source_id) REFERENCES public.finance_sources(household_id,id));
CREATE INDEX finance_transactions_household_date_idx ON public.finance_transactions(household_id,booked_on DESC);
CREATE INDEX finance_transactions_account_idx ON public.finance_transactions(household_id,account_id);
CREATE INDEX finance_transaction_sources_tx_idx ON public.finance_transaction_sources(household_id,transaction_id);
CREATE INDEX finance_sources_account_idx ON public.finance_sources(household_id,account_id);
CREATE FUNCTION public.finance_transaction_stamp() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $f$
BEGIN NEW.version:=OLD.version+1; NEW.updated_at:=now(); NEW.updated_by:=auth.uid(); NEW.category_method:='manual'; RETURN NEW; END $f$;
REVOKE ALL ON FUNCTION public.finance_transaction_stamp() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER finance_transactions_stamp BEFORE UPDATE ON public.finance_transactions FOR EACH ROW EXECUTE FUNCTION public.finance_transaction_stamp();
ALTER TABLE public.finance_accounts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.finance_sources ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.finance_transactions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.finance_transaction_sources ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.finance_accounts,public.finance_sources,public.finance_transactions,public.finance_transaction_sources FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.finance_accounts,public.finance_sources,public.finance_transactions,public.finance_transaction_sources TO authenticated;
GRANT UPDATE(category,flow_kind,review_status) ON public.finance_transactions TO authenticated;
GRANT ALL ON public.finance_accounts,public.finance_sources,public.finance_transactions,public.finance_transaction_sources TO service_role;
CREATE POLICY finance_accounts_read_member ON public.finance_accounts FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.finance_members m WHERE m.household_id=finance_accounts.household_id AND m.user_id=(SELECT auth.uid())));
CREATE POLICY finance_sources_read_member ON public.finance_sources FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.finance_members m WHERE m.household_id=finance_sources.household_id AND m.user_id=(SELECT auth.uid())));
CREATE POLICY finance_transactions_read_member ON public.finance_transactions FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.finance_members m WHERE m.household_id=finance_transactions.household_id AND m.user_id=(SELECT auth.uid())));
CREATE POLICY finance_transaction_sources_read_member ON public.finance_transaction_sources FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.finance_members m WHERE m.household_id=finance_transaction_sources.household_id AND m.user_id=(SELECT auth.uid())));
CREATE POLICY finance_transactions_edit_manager ON public.finance_transactions FOR UPDATE TO authenticated USING(EXISTS(SELECT 1 FROM public.finance_members m WHERE m.household_id=finance_transactions.household_id AND m.user_id=(SELECT auth.uid()) AND m.role='manager')) WITH CHECK(EXISTS(SELECT 1 FROM public.finance_members m WHERE m.household_id=finance_transactions.household_id AND m.user_id=(SELECT auth.uid()) AND m.role='manager'));
